#include <numeric>
#include <ostream>

class Fraction
{
public:
    Fraction(int numerator = 0, int denominator = 1);

    int numerator() const { return m_num; }
    int denominator() const { return m_den; }

private:
    int m_num{ 0 };
    int m_den{ 1 };
};

Fraction::Fraction(int numerator, int denominator)
    : m_num{ numerator }, m_den{ denominator == 0 ? 1 : denominator }
{
    if (m_den < 0)
    {
        m_num = -m_num;
        m_den = -m_den;
    }
    const int divisor{ std::gcd(m_num, m_den) };
    if (divisor > 1)
    {
        m_num /= divisor;
        m_den /= divisor;
    }
}

Fraction operator+(const Fraction& a, const Fraction& b)
{
    return { a.numerator() * b.denominator() + b.numerator() * a.denominator(), a.denominator() * b.denominator() };
}

Fraction operator-(const Fraction& a, const Fraction& b)
{
    return { a.numerator() * b.denominator() - b.numerator() * a.denominator(), a.denominator() * b.denominator() };
}

Fraction operator*(const Fraction& a, const Fraction& b)
{
    return { a.numerator() * b.numerator(), a.denominator() * b.denominator() };
}

Fraction operator/(const Fraction& a, const Fraction& b)
{
    return { a.numerator() * b.denominator(), a.denominator() * b.numerator() };
}

bool operator==(const Fraction& a, const Fraction& b)
{
    return a.numerator() == b.numerator() && a.denominator() == b.denominator();
}

bool operator<(const Fraction& a, const Fraction& b)
{
    return a.numerator() * b.denominator() < b.numerator() * a.denominator();
}

bool operator>(const Fraction& a, const Fraction& b)
{
    return b < a;
}

std::ostream& operator<<(std::ostream& out, const Fraction& f)
{
    out << f.numerator();
    if (f.denominator() != 1)
    {
        out << '/' << f.denominator();
    }
    return out;
}

unitTests:
std::string text(const Fraction& f) { std::ostringstream out; out << f; return out.str(); }

TEST("stored in lowest terms") { const Fraction f{ 6, 8 }; CHECK_EQ(f.numerator(), 3); CHECK_EQ(f.denominator(), 4); }
TEST("the sign lives on the numerator") { const Fraction f{ 2, -4 }; CHECK_EQ(f.numerator(), -1); CHECK_EQ(f.denominator(), 2); }
TEST("defaults") { CHECK_EQ(text(Fraction{}), "0"); CHECK_EQ(text(Fraction{ 5 }), "5"); }
TEST("arithmetic") { const Fraction a{ 3, 4 }, b{ 5, 6 }; CHECK_EQ(text(a + b), "19/12"); CHECK_EQ(text(a - b), "-1/12"); CHECK_EQ(text(a * b), "5/8"); CHECK_EQ(text(a / b), "9/10"); }
TEST("results reduce to whole numbers") { CHECK_EQ(text(Fraction{ 1, 2 } + Fraction{ 1, 2 }), "1"); CHECK_EQ(text(Fraction{ 2, 3 } * Fraction{ 3, 2 }), "1"); }
TEST("comparisons") { CHECK(Fraction{ 1, 2 } == Fraction{ 2, 4 }); CHECK(Fraction{ 1, 3 } < Fraction{ 1, 2 }); CHECK(Fraction{ 3, 4 } > Fraction{ 2, 3 }); CHECK(!(Fraction{ 1, 2 } < Fraction{ 1, 2 })); }

